/// <summary>
/// AVA/WEN/2025/07/03   AVA_013362_InventJournal_Count
/// </summary>
[ExtensionOf(classStr(InventJournalCheckPost_Movement))]
final class AVAInventJournalCheckPost_MovementCls_Extension
{
    private DialogField         dfBuildDiffJournal;

}

Method.Source:
/// <summary>
/// AVA/WEN/2025/07/03   AVA_013362_InventJournal_Count
/// </summary>
/// <returns>dialog</returns>
public Object dialog()
{
    InventJournalTrans  inventJournalTrans;
    DialogText          dt;

    select count(RecId) from inventJournalTrans
    where inventJournalTrans.JournalId == journalId
        &&  inventJournalTrans.NDXRecount == NoYes::Yes;

    Object dialogLoc = next dialog();

    if (journalTableId == tablenum(inventJournalTable)   &&
    InventJournalTable::find(journalId).JournalType == InventJournalType::Count &&
    journalCheckPostType == JournalCheckPostType::Post)
    {
        dfBuildDiffJournal  = dialogLoc.addFieldValue(enumStr(NoYes),strfmt("@NDX:NXACreateDiffJournal",inventJournalTrans.RecId), "@NDX:NXACreateDiffJournal2");
        if (inventJournalTrans.RecId)
        {
            dfBuildDiffJournal.value(NoYes::Yes);
        }
        else
        {
            dfBuildDiffJournal.value(NoYes::No);
            dfBuildDiffJournal.allowEdit(false);
            dt = dialog.addText("@NDX:NXANoPosMarked");        
        }
    }
    return dialogLoc;
}

public boolean getFromDialog()
{
    boolean ret;

    ret = next getFromDialog();

    nDXBuildDiffJournal = false;                                               
    if (journalTableId == tablenum(inventJournalTable)   &&
    InventJournalTable::find(journalId).JournalType == InventJournalType::Count &&
    journalCheckPostType == JournalCheckPostType::Post)
    {
        nDXBuildDiffJournal = dfBuildDiffJournal.value();
    }

    return ret;
}
